vulnerable_function:
Meteor.publish('activities', function(kind, id, limit, showActivities) {
  check(
    kind,
    Match.Where(x => {
      return ['board', 'card'].indexOf(x) !== -1;
    }),
  );
  check(id, Match.Maybe(String));
  check(limit, Number);
  check(showActivities, Boolean);

  // Return empty cursor if id is null or undefined
  if (!id) {
    return this.ready();
  }

  // Check user permissions - only BoardAdmin can view activities
  if (this.userId) {
    const user = ReactiveCache.getUser(this.userId);
    const board = ReactiveCache.getBoard(id);

    if (user && board) {
      // Find user membership in board
      const membership = board.members.find(m => m.userId === this.userId);

      // Only BoardAdmin can view activities
      if (!membership || !membership.isAdmin) {
        return this.ready();
      }
    } else {
      // If board or user not found, deny
      return this.ready();
    }
  } else {
    // If not logged in, deny
    return this.ready();
  }

  // Get linkedBoard
  let linkedElmtId = [id];
  if (kind == 'board') {
    ReactiveCache.getCards({
      "type": "cardType-linkedBoard",
      "boardId": id}
      ).forEach(card => {
        linkedElmtId.push(card.linkedId);
    });
  }

  const selector = showActivities
    ? { [`${kind}Id`]: { $in: linkedElmtId } }
    : { $and: [{ activityType: 'addComment' }, { [`${kind}Id`]: { $in: linkedElmtId } }] };
  const ret = ReactiveCache.getActivities(selector,
    {
      limit,
      sort: { createdAt: -1 },
    },
    true,
  );
  return ret;
}

patched_function:
Meteor.publish('activities', function(kind, id, limit, showActivities) {
  check(
    kind,
    Match.Where(x => {
      return ['board', 'card'].indexOf(x) !== -1;
    }),
  );
  check(id, Match.Maybe(String));
  check(limit, Number);
  check(showActivities, Boolean);

  // Return empty cursor if id is null or undefined
  if (!id) {
    return this.ready();
  }

  if (!this.userId) {
    return this.ready();
  }

  let linkedElmtId = [id];
  let board;

  if (kind === 'board') {
    board = ReactiveCache.getBoard(id);
    if (!board || !board.isVisibleBy(this.userId)) {
      return this.ready();
    }

    // Get linked boards, but only those visible to the user
    ReactiveCache.getCards({
      "type": "cardType-linkedBoard",
      "boardId": id
    }).forEach(card => {
      const linkedBoard = ReactiveCache.getBoard(card.linkedId);
      if (linkedBoard && linkedBoard.isVisibleBy(this.userId)) {
        linkedElmtId.push(card.linkedId);
      }
    });
  } else if (kind === 'card') {
    const card = ReactiveCache.getCard(id);
    if (!card) {
      return this.ready();
    }
    board = ReactiveCache.getBoard(card.boardId);
    if (!board || !board.isVisibleBy(this.userId)) {
      return this.ready();
    }
  }

  const selector = showActivities
    ? { [`${kind}Id`]: { $in: linkedElmtId } }
    : { $and: [{ activityType: 'addComment' }, { [`${kind}Id`]: { $in: linkedElmtId } }] };
  const ret = ReactiveCache.getActivities(selector,
    {
      limit,
      sort: { createdAt: -1 },
    },
    true,
  );
  return ret;
}

